class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        return mergeRange(lists, 0, lists.length - 1);
    }

    private ListNode mergeRange(ListNode[] lists, int left, int right) {
        if (left > right) {
            return null;
        }
        if (left == right) {
            return lists[left];
        }
        int middle = left + (right - left) / 2;
        ListNode first = mergeRange(lists, left, middle);
        ListNode second = mergeRange(lists, middle + 1, right);
        return mergeTwo(first, second);
    }

    private ListNode mergeTwo(ListNode first, ListNode second) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (first != null && second != null) {
            if (first.val <= second.val) {
                tail.next = first;
                first = first.next;
            } else {
                tail.next = second;
                second = second.next;
            }
            tail = tail.next;
        }
        tail.next = first != null ? first : second;
        return dummy.next;
    }
}
